// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import { CopyIcon, PipetteIcon } from 'lucide-react'

import {
  BrowserChrome,
  Btn,
  DemoStage,
  DockHeader,
  Label,
  type Build,
} from '@/app/demos/stage'

import { CAPTIONS, FINAL, PICKS } from './script'

const build: Build = ({ tl, q, step, final, move, click, scramble, wait, cursorOut, pos }) => {
  step(0)
  move('pick', { at: 0.3 })
  click('pick')
  const start = pos('pick')
  tl.set(q('loupe'), { x: start.x, y: start.y })
  tl.to(q('loupe'), { opacity: 1, scale: 1, duration: 0.4, ease: 'back.out(2)' })
  cursorOut('<')

  step(1, '+=0.1')
  PICKS.forEach((pick, index) => {
    const point = pos(pick.d)
    tl.to(
      q('loupe'),
      { x: point.x, y: point.y, duration: index === 0 ? 0.9 : 0.75, ease: 'power3.inOut' },
      index === 0 ? undefined : '+=0.25',
    )
    tl.to(q('loupe-fill'), { backgroundColor: pick.hex, duration: 0.25 }, '-=0.25')
  })

  step(2, '+=0.35')
  tl.to(q('loupe'), { scale: 0.85, duration: 0.1, yoyo: true, repeat: 1 })
  const from = pos(PICKS[2].d)
  const to = pos('swatch')
  tl.set(q('drop'), { x: from.x, y: from.y, opacity: 1, scale: 1 })
  tl.to(q('drop'), {
    motionPath: {
      path: [
        { x: from.x, y: from.y },
        { x: (from.x + to.x) / 2, y: Math.min(from.y, to.y) - 90 },
        { x: to.x, y: to.y },
      ],
      curviness: 1.3,
    },
    scale: 2.2,
    duration: 0.9,
    ease: 'power2.inOut',
  })
  tl.to(q('loupe'), { opacity: 0, scale: 0.6, duration: 0.3 }, '<')
  tl.to(q('swatch'), { backgroundColor: FINAL.hex, scale: 1.08, duration: 0.3 }, '-=0.15')
  tl.to(q('drop'), { opacity: 0, duration: 0.2 }, '<')
  tl.to(q('swatch'), { scale: 1, duration: 0.5, ease: 'elastic.out(1, 0.5)' })
  scramble('v-hex', FINAL.hex, { at: '<', duration: 0.6, chars: '0123456789abcdef' })
  scramble('v-rgb', FINAL.rgb, { at: '<0.1', duration: 0.7, chars: '0123456789' })
  scramble('v-hsl', FINAL.hsl, { at: '<0.1', duration: 0.7, chars: '0123456789' })

  step(3, '+=0.5')
  move('copy-hex')
  click('copy-hex')
  tl.fromTo(q('toast'), { opacity: 0, y: 8 }, { opacity: 1, y: 0, duration: 0.35 }, '<')
  cursorOut('+=0.3')
  final()
  wait(1.6)
  tl.to(q('toast'), { opacity: 0, duration: 0.3 })
}

export default function Demo() {
  return (
    <DemoStage
      label="Color Picker sampling colors from an image with a magnifying loupe and copying the HEX value"
      steps={CAPTIONS}
      build={build}
    >
      <BrowserChrome
        url="https://studio.example/poster"
        panelWidth={186}
        panel={
          <div className="flex h-full flex-col">
            <DockHeader />
            <div className="space-y-3 p-3">
              <Btn d="pick" primary className="w-full">
                <PipetteIcon className="size-3.5" /> Pick from screen
              </Btn>
              <div
                data-d="swatch"
                className="h-16 rounded-xl border border-line-strong bg-ink/5"
              />
              {[
                ['HEX', 'v-hex', '—', 'copy-hex'],
                ['RGB', 'v-rgb', '—', undefined],
                ['HSL', 'v-hsl', '—', undefined],
              ].map(([label, d, value, copy]) => (
                <div
                  key={label}
                  className="flex items-center gap-2 rounded-lg border border-line bg-canvas/70 px-2 py-1.5"
                >
                  <span className="w-7 font-mono text-[9px] text-muted">{label}</span>
                  <span data-d={d} className="flex-1 truncate font-mono text-[10.5px]">
                    {value}
                  </span>
                  <span data-d={copy} className="flex">
                    <CopyIcon className="size-3 text-muted" />
                  </span>
                </div>
              ))}
              <div>
                <Label>Or pick a color</Label>
                <span className="mt-1.5 block h-5 rounded-md border border-line-strong bg-black" />
              </div>
            </div>
            <span
              data-d="toast"
              className="absolute bottom-3 left-1/2 -translate-x-1/2 rounded-full bg-emerald px-2.5 py-1 text-[10px] font-medium text-canvas opacity-0"
            >
              Copied {FINAL.hex}
            </span>
          </div>
        }
      >
        <div className="relative h-full overflow-hidden bg-[#0e0e1a]">
          <div
            data-d="art-a"
            className="absolute -left-6 top-6 size-40 rounded-full bg-[#6366F1]"
          />
          <div
            data-d="art-b"
            className="absolute left-28 top-24 size-28 rounded-full bg-[#FBBF24] shadow-[0_0_80px_#fbbf2480]"
          />
          <div
            data-d="art-c"
            className="absolute bottom-0 right-0 h-36 w-48 rounded-tl-[80px] bg-[#F97362]"
          />
          <div className="absolute bottom-8 left-6 h-16 w-28 rounded-2xl bg-[#34d399]/80" />
          <p className="absolute left-6 top-4 text-[22px] font-black tracking-tight text-white/90">
            SUMMER/26
          </p>
        </div>
      </BrowserChrome>
      <div data-d="loupe" className="absolute left-0 top-0 z-40 -ml-9 -mt-9 scale-50 opacity-0">
        <div
          data-d="loupe-fill"
          className="size-[72px] rounded-full border-4 border-white bg-[#0e0e1a] shadow-[0_10px_30px_rgb(0_0_0/0.6)]"
        >
          <div className="size-full rounded-full [background-image:linear-gradient(rgb(0_0_0/0.25)_1px,transparent_1px),linear-gradient(90deg,rgb(0_0_0/0.25)_1px,transparent_1px)] [background-size:8px_8px]" />
          <span className="absolute left-1/2 top-1/2 size-2.5 -translate-x-1/2 -translate-y-1/2 border-2 border-white" />
        </div>
      </div>
      <span
        data-d="drop"
        className="absolute left-0 top-0 z-40 -ml-2 -mt-2 size-4 rounded-full border-2 border-white bg-[#F97362] opacity-0"
      />
    </DemoStage>
  )
}
